export class ApiError extends Error {}

function respond<T>(value: T, ms = 120): Promise<T> {
  const copy = value === undefined ? value : (JSON.parse(JSON.stringify(value)) as T);
  return new Promise((resolve) => setTimeout(() => resolve(copy), ms));
}

function fail(message: string): never {
  throw new ApiError(message);
}

function commit<T>(value: T, ms?: number): Promise<T> {
  persist();
  return respond(value, ms);
}

const findUser = (id: ID) => db.users.find((u) => u.id === id) ?? fail('Хэрэглэгч олдсонгүй');
const findCompany = (id: ID) => db.companies.find((c) => c.id === id) ?? fail('Байгууллага олдсонгүй');
const findBranch = (id: ID) => db.branches.find((b) => b.id === id) ?? fail('Салбар олдсонгүй');
const findRole = (id: ID) => db.roles.find((r) => r.id === id) ?? fail('Үүрэг олдсонгүй');

const userRef = (u: User) => ({ id: u.id, name: u.name, shortName: u.shortName });

function activeMembership(userId: ID, companyId: ID): Membership | undefined {
  return db.memberships.find((m) => m.userId === userId && m.companyId === companyId && m.status === 'active');
}

function permissionsOf(m: Membership): Permission[] {
  return findRole(m.roleId).permissions;
}

function membersWith(companyId: ID, permission: Permission): ID[] {
  return db.memberships
    .filter((m) => m.companyId === companyId && m.status === 'active' && permissionsOf(m).includes(permission))
    .map((m) => m.userId);
}

function requirePerm(userId: ID, companyId: ID, permission: Permission, message: string) {
  const m = activeMembership(userId, companyId);
  if (!m || !permissionsOf(m).includes(permission)) fail(message);
  return m;
}

/** The mock has no server-side identity; the backend enforces platform-admin access. */
function requireAdminMock() {}

function notify(userIds: ID[], text: string, link: string) {
  for (const userId of new Set(userIds)) {
    db.notifications.unshift({
      id: uid('n'),
      userId,
      text,
      link,
      read: false,
      createdAt: new Date().toISOString(),
    });
  }
}

const firstName = (u: User) => u.name.split(' ')[0];
const ddmm = (iso: ISODate) => iso.slice(5).replace('-', '/');

function toListItem(job: Job): JobListItem {
  const company = findCompany(job.companyId);
  const branch = findBranch(job.branchId);
  return {
    ...job,
    company: { id: company.id, name: company.name, initials: company.initials },
    branch: { id: branch.id, name: branch.name, district: branch.district },
  };
}

function isOnLeave(userId: ID, date: ISODate): boolean {
  return db.leave.some(
    (l) => l.userId === userId && l.status === 'approved' && l.startDate <= date && l.endDate >= date,
  );
}

function shiftFor(userId: ID, date: ISODate) {
  const s = db.shifts.find((x) => x.userId === userId && x.date === date);
  return s ? { slot: s.slot, ...SHIFT_SLOTS[s.slot] } : null;
}

/** Working hours a member is expected on a date, or null if off. */
function expectedHours(m: Membership, date: ISODate) {
  if (m.scheduleType === 'shift') return shiftFor(m.userId, date);
  const dow = parseDate(date).getDay();
  if (dow === 0 || dow === 6) return null;
  return { slot: null, label: 'Тогтмол', start: FIXED_HOURS.start, end: FIXED_HOURS.end };
}

