    const m = activeMembership(byUserId, input.companyId);
    if (!m || !permissionsOf(m).includes('job.create')) fail('Танд ажлын зар нийтлэх эрх алга');
    const job: Job = { ...input, id: uid('j'), createdAt: new Date().toISOString() };
    db.jobs.unshift(job);
